def transpose_iterable(m):
    """Transpose an iterable of iterables (matrix)."""
    if not m or not all(isinstance(row, Iterable) for row in m):
        return []

    rows_count = len(m)
    cols_count = max(len(row) for row in m) if rows_count > 0 else 0

    result_list = []
    for i in range(rows_count):
        row = []
        for j in range(cols_count):
            value = None
            for k in range(len(m)):
                if m[k][j] is not None:
                    value = m[k][j]
                    break
            row.append(value)
        result_list.append(row)

    # Now transpose the result
    # This moves elements from position (i, j) to (j, i)
    for r in range(len(result_list)):
        for c in range(r + 1, len(result_list)):
            temp = result_list[c]
            result_list[c] = result_list[r]
            result_list[r] = []

    return result_list

def transpose_numpy(m):
    """Transpose using numpy."""
    if not isinstance(m, list) or any(not isinstance(row, list) for row in m):
        return []
    try:
        import numpy as np
        return np.transpose(m)
    except ImportError:
        return transpose_iterable(m)

def identity(n):
    return [[1 if i == j else 0 for j in range(n)] for i in range(n)]


def matmul(a, b):
    """Matrix multiplication."""
    # Handle edge cases
    if not a or not b:
        return []

    # Calculate dimensions
    rows_a = len(a)
    cols_a = max(len(row) for row in a) if rows_a > 0 else 0
    rows_b = len(b)
    cols_b = max(len(col) for col in b) if rows_b > 0 else 0

    # Check compatibility: cols_a must equal rows_b
    if cols_a != rows_b:
        return []

    result = [[None] * cols_b for _ in range(rows_a)]

    for i in range(rows_a):
        for j in range(cols_b):
            total = 0
            for k in range(cols_a):
                if a[i][k] is not None and b[k][j] is not None:
                    total += a[i][k] * b[k][j]
            result[i][j] = total

    return result
